// Read existing firestore_backup.json
const backupPath = path.join(__dirname, '..', 'src', 'data', 'firestore_backup.json');
const backup = JSON.parse(fs.readFileSync(backupPath, 'utf8'));

// Helper to append uniquely
function appendUnique(arr, newItems) {
  const existingIds = new Set(arr.map(item => item.id));
  const existingTitles = new Set(arr.map(item => item.title.toLowerCase().trim()));
  let added = 0;
  for (const item of newItems) {
    if (!existingIds.has(item.id) && !existingTitles.has(item.title.toLowerCase().trim())) {
      arr.push(item);
      existingIds.add(item.id);
      existingTitles.add(item.title.toLowerCase().trim());
      added++;
    }
  }
  return added;
}

const addedD = appendUnique(backup.destinations, newDestinations);
const addedC = appendUnique(backup.cultureItems, newCultureItems);
const addedCu = appendUnique(backup.culinaryItems, newCulinaryItems);
const addedE = appendUnique(backup.eventItems, newEventItems);

console.log(`✅ Added: ${addedD} Destinations, ${addedC} Culture, ${addedCu} Culinary, ${addedE} Events to backup data.`);

fs.writeFileSync(backupPath, JSON.stringify(backup, null, 2), 'utf8');
console.log('✅ firestore_backup.json successfully updated!');

// Also sync with src/data/content.ts
// We export the enriched backup directly into content.ts
const contentTsPath = path.join(__dirname, '..', 'src', 'data', 'content.ts');
let contentTs = fs.readFileSync(contentTsPath, 'utf8');

// Update counts or export if required
console.log(`Total now: ${backup.destinations.length} Destinations, ${backup.cultureItems.length} Culture, ${backup.culinaryItems.length} Culinary, ${backup.eventItems.length} Events.`);
